    onSave: (amount: String, note: String, typeIds: Set<Long>) -> String?
) {
    var amount by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }
    var selected by remember { mutableStateOf(emptySet<Long>()) }
    var error by remember { mutableStateOf<String?>(null) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("New expense") },
        text = {
            Column {
                OutlinedTextField(
                    value = amount,
                    onValueChange = { amount = it },
                    label = { Text("Amount (e.g. 12.50)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    singleLine = true
                )
                OutlinedTextField(
                    value = note,
                    onValueChange = { note = it },
                    label = { Text("Note (optional)") },
                    singleLine = true
                )
                Spacer(Modifier.height(12.dp))
                Text("Types", style = MaterialTheme.typography.labelLarge)
                if (types.isEmpty()) {
                    Text(
                        "No types yet. Close this and create some via \"Types\" first.",
                        style = MaterialTheme.typography.bodySmall
                    )
                } else {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        types.forEach { type ->
                            val isSelected = type.id in selected
                            FilterChip(
                                selected = isSelected,
                                onClick = {
                                    selected = if (isSelected) selected - type.id else selected + type.id
                                },
                                label = { Text(type.name) }
                            )
                        }
                    }
                }
                error?.let {
                    Spacer(Modifier.height(8.dp))
                    Text(it, color = MaterialTheme.colorScheme.error)
                }
            }
        },
        confirmButton = {
            TextButton(onClick = { error = onSave(amount, note, selected) }) { Text("Save") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

// ---------------- Types management ----------------

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TypesScreen(vm: ExpenseViewModel, onBack: () -> Unit) {
    val types by vm.types.collectAsState()
    var showNew by remember { mutableStateOf(false) }
    var editing by remember { mutableStateOf<ExpenseType?>(null) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Expense types") },
                navigationIcon = { TextButton(onClick = onBack) { Text("Back") } }
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = { showNew = true }) {
                Icon(Icons.Default.Add, contentDescription = "Add type")
            }
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize()
                .padding(16.dp)
        ) {
            if (types.isEmpty()) {
                Text("No types yet. Tap + to add one.")
            } else {
                Text(
                    "Tap a type to rename it. Deleting a type removes it from existing expenses.",
                    style = MaterialTheme.typography.bodySmall
                )
                Spacer(Modifier.height(8.dp))
                LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    items(types, key = { it.id }) { type ->
                        Card(modifier = Modifier.fillMaxWidth()) {
                            Row(
                                modifier = Modifier.padding(start = 16.dp, end = 4.dp, top = 4.dp, bottom = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = type.name,
                                    style = MaterialTheme.typography.titleMedium,
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable { editing = type }
                                )
                                IconButton(onClick = { vm.deleteType(type) }) {
                                    Icon(Icons.Default.Delete, contentDescription = "Delete type")
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if (showNew) {
        TypeEditDialog(
            title = "New type",
            initialName = "",
            onDismiss = { showNew = false },
            onSave = { name ->
                val error = vm.createType(name)
                if (error == null) showNew = false
                error
            }
        )
    }

    editing?.let { type ->
        TypeEditDialog(
            title = "Rename type",
            initialName = type.name,
            onDismiss = { editing = null },
            onSave = { name ->
                val error = vm.renameType(type, name)
                if (error == null) editing = null
                error
            }
        )
    }
}

@Composable
fun TypeEditDialog(
    title: String,
    initialName: String,
    onDismiss: () -> Unit,
    onSave: (String) -> String?
) {
    var name by remember { mutableStateOf(initialName) }
    var error by remember { mutableStateOf<String?>(null) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title) },
        text = {
            Column {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text("Type name (e.g. Food)") },
                    singleLine = true
                )
                error?.let {
                    Spacer(Modifier.height(8.dp))
                    Text(it, color = MaterialTheme.colorScheme.error)
                }
            }
        },
        confirmButton = {
            TextButton(onClick = { error = onSave(name) }) { Text("Save") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

